let S=JSON.parse(localStorage.getItem(LS)||'{}');S={route:'home',location:'DHA Phase 5',category:'Makeup',...S};const save=()=>localStorage.setItem(LS,JSON.stringify(S));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const $=q=>document.querySelector(q);const app=()=>$('#beautyApp');
function authUsers(){try{return JSON.parse(localStorage.getItem(AUTH_USERS_KEY)||'[]')}catch(e){return []}}
function saveAuthUsers(users){localStorage.setItem(AUTH_USERS_KEY,JSON.stringify(users))}
function authSession(){try{return JSON.parse(localStorage.getItem(AUTH_SESSION_KEY)||'null')}catch(e){return null}}
function currentUser(){let session=authSession();return session?authUsers().find(u=>u.id===session.userId)||null:null}
function isAdmin(){return currentUser()?.role==='admin'}
function isAdminRoute(route){return ['admin-profile','beauty-verifications','beauty-verification-review'].includes(route)}
function nav(route,data={}){if(isAdminRoute(route)&&!isAdmin())route=currentUser()?'user-profile':'login';if(route==='verify-info'&&S.route!=='verify-info')sessionStorage.removeItem(VOICE_WHATSAPP_OPENED);Object.assign(S,data,{route});save();render();scrollTo(0,0)}
function head(title,sub='',back='beauty-main'){return `<div class="beauty-head"><button class="back" onclick="nav('${back}')">‹</button><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div></div>`}
function bottom(){return `<div class="beauty-bottom-space"></div>`}
function setBeauty(on){$('#homePage').classList.toggle('hidden',on);$('#beautyApp').classList.toggle('hidden',!on);document.body.classList.toggle('beauty-mode',on)}
function render(){let user=currentUser(),authRoute=['login','signup'].includes(S.route);if(!user&&!authRoute){S.route='login';save();authRoute=true}if(user&&authRoute){S.route=user.role==='admin'?'admin-profile':'home';save();authRoute=false}if(isAdminRoute(S.route)&&!isAdmin()){S.route=user?'user-profile':'login';save()}document.body.classList.toggle('auth-mode',authRoute);document.body.classList.toggle('profile-mode',['user-profile','admin-profile'].includes(S.route));if(authRoute){setBeauty(true);app().className='beauty-shell auth-shell';app().innerHTML=S.route==='signup'?signUpPage():loginPage();return}if(S.route==='home'){setBeauty(false);return}setBeauty(true);syncApprovedBeautyProvider();app().className='beauty-shell';app().classList.add(...([]));app().classList.remove('create-profile-screen','verify-info-screen','pending-page','admin-verifications-screen','admin-review-screen','user-profile-screen','admin-profile-screen','auth-shell');let h='';
 if(S.route==='beauty-main')h=main(); if(S.route==='categories')h=categories(); if(S.route==='results')h=results(); if(S.route==='profile')h=profile(S.provider||'ayesha'); if(S.route==='create'){app().classList.add('create-profile-screen');h=createProfile()} if(S.route==='verify-info'){app().classList.add('verify-info-screen');h=verifyInfo()} if(S.route==='pending')h=pending(); if(S.route==='contacts')h=contacts(); if(S.route==='confirm')h=confirmService(); if(S.route==='rate')h=rate(); if(S.route==='user-profile'){app().classList.add('user-profile-screen');h=userProfilePage()} if(S.route==='admin-profile'){app().classList.add('admin-profile-screen');h=adminProfilePage()} if(S.route==='beauty-verifications'){app().classList.add('admin-verifications-screen');h=beautyVerifications()} if(S.route==='beauty-verification-review'){app().classList.add('admin-review-screen');h=beautyVerificationReview()} app().innerHTML=h+bottom();}
function authLogo(){return `<img class="auth-logo" src="logo_herday.webp" alt="HerDay">`}
function authField(id,label,type,placeholder,icon,required=true,autocomplete=''){return `<label class="auth-field-label" for="${id}">${label}</label><div class="auth-field"><span>${icon}</span><input id="${id}" type="${type}" placeholder="${placeholder}" ${required?'required':''} ${autocomplete?`autocomplete="${autocomplete}"`:''}></div>`}
function socialButtons(){return `<div class="auth-divider"><span>or continue with</span></div><button class="auth-social" onclick="socialAuth('google')"><img class="google-mark" src="google_g.svg" alt="">Continue with Google</button><button class="auth-social" onclick="socialAuth('facebook')"><b class="facebook-mark">f</b>Continue with Facebook</button>`}
function loginPage(){return `<div class="auth-page">${authLogo()}<h1>Welcome back</h1><p class="auth-subtitle">Log in to continue to HerDay.</p><form class="auth-card" onsubmit="loginAccount(event)">${authField('loginEmail','Email','email','Enter your email','✉',true,'email')}${authField('loginPassword','Password','password','Enter your password','♙',true,'current-password')}<button type="button" class="auth-link forgot" onclick="forgotPassword()">Forgot Password?</button><button class="btn primary auth-primary" type="submit">Log In</button>${socialButtons()}</form><p class="auth-switch">Don't have an account? <button onclick="nav('signup')">Sign Up</button></p></div>`}
function signUpPage(){return `<div class="auth-page signup-page">${authLogo()}<h1>Create your account</h1><p class="auth-subtitle">Join HerDay and make it yours.</p><form class="auth-card" onsubmit="createAccount(event)">${authField('signupFirst','First Name','text','Enter first name','♙',true,'given-name')}${authField('signupLast','Last Name','text','Enter last name','♙',true,'family-name')}${authField('signupEmail','Email','email','Enter your email','✉',true,'email')}${authField('signupCell','Cell Number <span>(Optional)</span>','tel','Enter cell number','⌕',false,'tel')}${authField('signupPassword','Password','password','Create a password','♙',true,'new-password')}${authField('signupConfirm','Confirm Password','password','Confirm your password','♙',true,'new-password')}<button class="btn primary auth-primary" type="submit">Create Account</button><p class="auth-terms">By creating an account, you agree to HerDay's<br><button type="button" onclick="showPlaceholder('Terms & Privacy Policy')">Terms &amp; Privacy Policy.</button></p>${socialButtons()}</form><p class="auth-switch">Already have an account? <button onclick="nav('login')">Log In</button></p></div>`}
async function passwordDigest(value){let data=new TextEncoder().encode(value);if(globalThis.crypto?.subtle){let hash=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}return btoa(unescape(encodeURIComponent(value)))}
async function createAccount(event){event.preventDefault();let first=$('#signupFirst').value.trim(),last=$('#signupLast').value.trim(),email=$('#signupEmail').value.trim().toLowerCase(),cell=$('#signupCell').value.trim(),password=$('#signupPassword').value,confirmPassword=$('#signupConfirm').value;if(!first||!last||!email||!password||!confirmPassword){alert('Please complete all required fields.');return}if(password!==confirmPassword){alert('Passwords do not match.');return}if(password.length<6){alert('Password must be at least 6 characters.');return}let users=authUsers();if(users.some(u=>u.email===email)){alert('An account with this email already exists.');return}let user={id:'user-'+Date.now(),firstName:first,lastName:last,email,cell,photo:'',role:'user',passwordHash:await passwordDigest(password),createdAt:new Date().toISOString()};users.push(user);saveAuthUsers(users);localStorage.setItem(AUTH_SESSION_KEY,JSON.stringify({userId:user.id,createdAt:new Date().toISOString()}));S.route='home';save();render();scrollTo(0,0)}
function ensureDevelopmentBeautyTestRecord(){if(pendingBeautyVerifications().length||S.newName)return;Object.assign(S,DEVELOPMENT_BEAUTY_TEST_RECORD,{verificationSubmittedAt:new Date().toISOString()});save()}
function developmentDemoAdminLogin(email,password){if(email!==DEVELOPMENT_DEMO_ADMIN.email||password!==DEVELOPMENT_DEMO_ADMIN.password)return null;let users=authUsers(),index=users.findIndex(u=>u.id===DEVELOPMENT_DEMO_ADMIN.id),user={id:DEVELOPMENT_DEMO_ADMIN.id,firstName:DEVELOPMENT_DEMO_ADMIN.firstName,lastName:DEVELOPMENT_DEMO_ADMIN.lastName,email:DEVELOPMENT_DEMO_ADMIN.email,cell:'',photo:'',role:DEVELOPMENT_DEMO_ADMIN.role,passwordHash:'DEVELOPMENT_TESTING_ONLY',createdAt:users[index]?.createdAt||new Date().toISOString()};if(index<0)users.push(user);else users[index]=user;saveAuthUsers(users);ensureDevelopmentBeautyTestRecord();return user}
async function loginAccount(event){event.preventDefault();let email=$('#loginEmail').value.trim().toLowerCase(),password=$('#loginPassword').value,user=developmentDemoAdminLogin(email,password);if(!user){user=authUsers().find(u=>u.email===email);if(!user||user.passwordHash!==await passwordDigest(password)){alert('Email or password is incorrect.');return}}localStorage.setItem(AUTH_SESSION_KEY,JSON.stringify({userId:user.id,createdAt:new Date().toISOString()}));S.route=user.role==='admin'?'admin-profile':'home';save();render();scrollTo(0,0)}
function socialAuth(provider){let adapter=window.HerDayAuthAdapters?.[provider];if(typeof adapter==='function'){adapter();return}alert(`${provider==='google'?'Google':'Facebook'} authentication requires external provider configuration. No account was created.`)}
function forgotPassword(){alert('Password reset requires the production authentication provider. No reset request was sent in this local test build.')}
function signOut(){localStorage.removeItem(AUTH_SESSION_KEY);S.route='login';save();render();scrollTo(0,0)}
function openProfile(){let user=currentUser();nav(!user?'login':user.role==='admin'?'admin-profile':'user-profile')}
function userFullName(user){return [user?.firstName,user?.lastName].filter(Boolean).join(' ')||'HerDay User'}
function accountAvatar(user,extra=''){return `<div class="account-avatar ${extra}">${user?.photo?`<img src="${esc(user.photo)}" alt="${esc(userFullName(user))} profile photo">`:'♙'}</div>`}
function profileHeader(title){return `<div class="account-header"><img src="logo_herday.webp" alt="HerDay"><img src="ic_notification_bell_final.webp" alt="Notifications"></div><h1 class="account-page-title">${title}</h1>`}
function profileIdentity(user,admin=false){return `<div class="account-identity bcard">${accountAvatar(user)}<div><h2>${esc(userFullName(user))}</h2><p>${esc(user.email)}</p>${admin?'<span class="admin-badge">♛ &nbsp; Admin</span>':'<button class="btn secondary edit-profile-button" onclick="showEditProfileDialog()">♙ &nbsp; Edit Profile</button>'}</div><span class="account-chevron">›</span></div>`}
function beautyProfileStateCard(){let user=currentUser(),owns=!!user&&S.beautyOwnerId===user.id,state=owns?(S.verification||'none'):'none';if(!owns||!S.newName)return `<div class="profile-feature-card"><span class="profile-module-icon">♧</span><div><h3>Create Beauty Profile</h3><p>Offer your beauty services through a professional Beauty Profile on HerDay.</p><button class="profile-pill" onclick="nav('create')">Create Beauty Profile &nbsp;›</button></div></div>`;if(state==='pending')return `<div class="profile-feature-card"><span class="profile-module-icon">◷</span><div><h3>${esc(S.newName)}</h3><span class="status wait">Pending Review</span><p>Your Beauty Profile verification is awaiting HerDay review.</p><button class="profile-pill" onclick="nav('pending')">View Verification Status &nbsp;›</button></div></div>`;if(state==='needs-correction')return `<div class="profile-feature-card correction"><span class="profile-module-icon">ⓘ</span><div><h3>Needs Correction</h3><p>${esc(S.verificationCorrection?.reason||'HerDay requested a correction to your Beauty Profile.')}</p>${S.verificationCorrection?.note?`<div class="profile-admin-note">${esc(S.verificationCorrection.note)}</div>`:''}<button class="profile-pill" onclick="nav('create')">Review Beauty Profile &nbsp;›</button></div></div>`;if(state==='approved'&&S.beautyVerified===true)return `<div class="profile-feature-card approved"><span class="profile-module-icon">✓</span><div><div class="row between"><h3>${esc(S.newName)}</h3><span class="verified-professional">Verified ✓</span></div><p>Your professional Beauty Profile is approved and eligible to be public.</p><div class="profile-management"><button onclick="nav('profile',{provider:'submitted-beauty-profile'})">My Beauty Profile &nbsp;›</button><button onclick="nav('contacts')">Service Contacts &nbsp;›</button></div></div></div>`;return `<div class="profile-feature-card"><span class="profile-module-icon">♧</span><div><h3>Complete Beauty Profile</h3><p>Continue your professional Beauty Profile verification.</p><button class="profile-pill" onclick="nav('verify-info')">Continue Verification &nbsp;›</button></div></div>`}
function accountRow(icon,title,action){return `<button class="account-row" onclick="${action}"><span>${icon}</span><b>${title}</b><i>›</i></button>`}
function userProfilePage(){let user=currentUser();return `${profileHeader('Profile')}${profileIdentity(user)}<h2 class="account-section-title">Beauty Services</h2>${beautyProfileStateCard()}<h2 class="account-section-title">Account</h2><div class="account-list">${accountRow('⚙','Account Settings',`showPlaceholder('Account Settings')`)}${accountRow('♢','Privacy & Safety',`showPlaceholder('Privacy & Safety')`)}${accountRow('?','Help & Support',`showPlaceholder('Help & Support')`)}</div><button class="account-signout" onclick="signOut()"><span>↪</span>Sign Out<i>›</i></button>`}
const ADMIN_MODULES=[['♧','Beauty Services','Beauty Verifications','Review and verify submitted Beauty Profiles.','beauty-verifications'],['☵','Moderation','','Review content and submissions across HerDay.','future'],['♙♙','Users','','Manage HerDay user accounts.','future'],['♢','Reports & Safety','','Review reported content, users and safety concerns.','future'],['▢','Shop','','Manage HerDay Shop content and activity.','future'],['▤','Content & Explore','','Manage Explore and approved HerDay content.','future'],['⌁','Advertising','','Manage HerDay advertising.','future']];
function adminProfilePage(){let user=currentUser();if(!user||user.role!=='admin')return '';let pending=pendingBeautyVerifications().length;return `${profileHeader('Admin Profile')}${profileIdentity(user,true)}<h2 class="account-section-title">Admin Tools</h2><div class="admin-modules">${ADMIN_MODULES.map(m=>`<button class="admin-module ${m[4]==='beauty-verifications'?'functional':''}" onclick="${m[4]==='beauty-verifications'?`nav('beauty-verifications')`:`showPlaceholder('${m[1]}')`}"><span class="profile-module-icon">${m[0]}</span><div><h3>${m[1]}</h3>${m[2]?`<b>${m[2]}</b>`:''}<p>${m[3]}</p></div>${m[4]==='beauty-verifications'&&pending?`<em>${pending} Pending</em>`:''}<i>›</i></button>`).join('')}</div><h2 class="account-section-title">Account</h2><div class="account-list">${accountRow('♙','Edit Profile','showEditProfileDialog()')}${accountRow('⚙','Account Settings',`showPlaceholder('Account Settings')`)}</div><button class="account-signout" onclick="signOut()"><span>↪</span>Sign Out<i>›</i></button>`}
function showPlaceholder(title){alert(`${title} will be implemented in its dedicated module.`)}
function showEditProfileDialog(){let user=currentUser();if(!user)return;adminDialog(`<h2>Edit Profile</h2><p>Update your HerDay personal profile details.</p><label class="dialog-label">First Name</label><input id="editFirst" class="field" value="${esc(user.firstName||'')}"><label class="dialog-label">Last Name</label><input id="editLast" class="field" value="${esc(user.lastName||'')}"><label class="dialog-label">Cell Number <span>(Optional)</span></label><input id="editCell" class="field" value="${esc(user.cell||'')}"><label class="dialog-label upload-profile-photo">Profile Photo<input id="editPhoto" type="file" accept="image/*"></label><div class="admin-dialog-actions"><button class="btn secondary" onclick="closeAdminDialog()">Cancel</button><button class="btn primary" onclick="savePersonalProfile()">Save Changes</button></div>`)}
function savePersonalProfile(){let user=currentUser();if(!user)return;let first=$('#editFirst').value.trim(),last=$('#editLast').value.trim();if(!first||!last){alert('First and Last Name are required.');return}let finish=photo=>{let users=authUsers(),index=users.findIndex(u=>u.id===user.id);users[index]={...users[index],firstName:first,lastName:last,cell:$('#editCell').value.trim(),photo:photo??users[index].photo};saveAuthUsers(users);closeAdminDialog();render()};let file=$('#editPhoto').files?.[0];if(!file){finish();return}let reader=new FileReader();reader.onload=()=>finish(reader.result);reader.readAsDataURL(file)}
function icon(c){const m={'Makeup':'💄','Bridal Services':'♕','Hair':'〰','Mehndi':'✋','Skin & Facial':'◉','Waxing':'✦','Threading & Brows':'⌁','Nails':'▯','Manicure & Pedicure':'✋','Lashes':'◡','Massage & Relaxation':'✿','Other Beauty Services':'✧'};return m[c]||'✦'}
function locationCity(){let d=S.locationDetail||S.location||'';let parts=d.split(',').map(x=>x.trim()).filter(Boolean);let area=(S.location||'').trim().toLowerCase();let skip=new Set([area,'punjab','pakistan','pakistan.']);let city=parts.find(x=>!skip.has(x.toLowerCase())&&!/district|tehsil|division|province|postcode|postal/i.test(x));return city||S.location||'Selected Location'}
function main(){return head('Beauty Services','Beauty, closer to you.','home')+`<div class="bcard loc-card"><div class="loc-tabs"><button class="active" onclick="nearMe()">⌾ &nbsp; Near Me</button><button onclick="chooseLocation()">⌖ &nbsp; Choose Location ›</button></div><div class="location-now"><span class="round-icon">⌖</span><div><b>${esc(locationCity())}</b><div class="muted">${esc(S.location)}</div></div></div><div class="divider"></div><div class="muted">Find beauty professionals who serve this area.</div></div><input class="searchbox" placeholder="What service are you looking for?" onkeydown="if(event.key==='Enter'){S.category=this.value||'Makeup';nav('results')}"><div class="row between"><h2 class="section-title">Explore Beauty</h2><button class="danger-link" onclick="nav('categories')">View all&nbsp; ›</button></div><div class="quick-grid">${B.quick.map(c=>`<button class="quick" onclick="nav('results',{category:'${c}'})"><span class="cat-icon">${icon(c)}</span><b>${c.replace('Skin & Facial','Skin / Facial')}</b></button>`).join('')}</div><div style="height:16px"></div><button class="btn primary" onclick="nav('results')">Find Providers &nbsp; ›</button><div class="bcard provider-cta"><span class="round-icon">♙</span><div><b>Do you offer beauty services?</b><div class="muted">Create your professional Beauty Profile on HerDay.</div><button class="btn secondary" onclick="nav('create')">Create Beauty Profile &nbsp; ›</button></div></div>`}
const APP_LOCATIONS=()=>[...new Set([...B.providers.flatMap(p=>p.areas),...(S.savedLocations||[]),...(S.newAreas||[])])];
let locationTimer=null;
function chooseLocation(){
 document.body.insertAdjacentHTML('beforeend',`<div id="locationPanel" class="location-panel" onclick="if(event.target===this)closeLocationSearch()"><div class="location-sheet"><div class="row between"><div><h2>Choose Location</h2><div class="muted">Search an area or address</div></div><button class="back" onclick="closeLocationSearch()">×</button></div><input id="locationQuery" class="field" autocomplete="off" placeholder="Search area, locality or address" oninput="locationInput(this.value)"><div id="locationResults" class="location-results"></div></div></div>`);
 renderLocationResults('',APP_LOCATIONS().map(x=>({name:x,detail:'Saved on HerDay'})));
 setTimeout(()=>$('#locationQuery')?.focus(),50);
}
function closeLocationSearch(){$('#locationPanel')?.remove()}
function locationInput(q){clearTimeout(locationTimer);q=q.trim();let local=APP_LOCATIONS().filter(x=>x.toLowerCase().includes(q.toLowerCase())).map(x=>({name:x,detail:'Saved on HerDay'}));renderLocationResults(q,local);if(q.length<3)return;locationTimer=setTimeout(()=>searchMapLocations(q,local),350)}
async function searchMapLocations(q,local=[]){let box=$('#locationResults');if(box)box.insertAdjacentHTML('beforeend','<div class="location-loading">Searching map locations…</div>');try{let u='https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=7&countrycodes=pk&q='+encodeURIComponent(q);let r=await fetch(u,{headers:{'Accept':'application/json'}});if(!r.ok)throw 0;let data=await r.json();let map=data.map(x=>({name:x.name||x.address?.suburb||x.address?.neighbourhood||x.display_name.split(',')[0],detail:x.display_name,lat:x.lat,lon:x.lon}));let seen=new Set(),all=[...local,...map].filter(x=>{let n=(x.name||'').trim().toLowerCase().replace(/\bdistrict\b/g,'').replace(/[^a-z0-9\s]/g,'').replace(/\s+/g,' ').trim();let d=(x.detail||'').toLowerCase().replace(/[^a-z0-9\s]/g,'').replace(/\s+/g,' ').trim();let lat=x.lat?Number(x.lat).toFixed(2):'',lon=x.lon?Number(x.lon).toFixed(2):'';let k=n+'|'+lat+'|'+lon;if(seen.has(n)||seen.has(k)||seen.has(n+'|'+d))return false;seen.add(n);seen.add(k);seen.add(n+'|'+d);return true}).slice(0,6);renderLocationResults(q,all)}catch(e){renderLocationResults(q,local,true)}}
function renderLocationResults(q,items,failed=false){let box=$('#locationResults');if(!box)return;box.innerHTML=items.length?items.map((x,i)=>`<button class="location-option" onclick='selectLocation(${JSON.stringify(JSON.stringify(x))})'><b>⌖ &nbsp;${esc(x.name)}</b><small>${esc(x.detail||'')}</small></button>`).join(''):`<div class="location-loading">${failed?'Map search unavailable. Try again.':q?'No matching location yet.':'Type to search map locations.'}</div>`}
function selectLocation(raw){let x=typeof raw==='string'?JSON.parse(raw):raw;S.location=x.name;S.locationDetail=x.detail||x.name;S.locationCoords=x.lat&&x.lon?{lat:+x.lat,lon:+x.lon}:null;S.savedLocations=[...new Set([...(S.savedLocations||[]),x.name])];save();closeLocationSearch();render()}
function nearMe(){if(!navigator.geolocation){alert('Location is not available in this browser.');return}navigator.geolocation.getCurrentPosition(async pos=>{try{let u=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`;let r=await fetch(u,{headers:{'Accept':'application/json'}});let x=await r.json();let a=x.address||{};let name=a.suburb||a.neighbourhood||a.quarter||a.city_district||a.city||a.town||a.village||x.name||'Current Location';selectLocation(JSON.stringify({name,detail:x.display_name||name,lat:pos.coords.latitude,lon:pos.coords.longitude}))}catch(e){S.location='Current Location';S.locationCoords={lat:pos.coords.latitude,lon:pos.coords.longitude};save();render()}},()=>alert('Allow location permission to use Near Me.'),{enableHighAccuracy:true,timeout:10000,maximumAge:60000})}
function categories(){return head('All Beauty Categories','What are you looking for?')+`<div class="cat-grid">${B.cats.map(c=>`<button class="cat" onclick="nav('results',{category:'${c}'})"><span class="cat-icon">${icon(c)}</span><b>${c}</b></button>`).join('')}</div>`}
function results(){let ps=B.providers.filter(p=>p.areas.includes(S.location)&&(p.cats.includes(S.category)||p.services.some(x=>x.toLowerCase().includes(S.category.toLowerCase()))));if(!ps.length)ps=B.providers.filter(p=>p.areas.includes(S.location));return head('Beauty Professionals',`${esc(S.category)} · ${esc(S.location)}`)+`<div class="bcard result-context"><div><span class="round-icon">${icon(S.category)}</span><span class="muted">Service</span><br><b>${esc(S.category)}</b><button class="btn secondary" onclick="nav('categories')">Change Service</button></div><div><span class="round-icon">⌖</span><span class="muted">Location</span><br><b>${esc(S.location)}</b><button class="btn secondary" onclick="chooseLocation()">Change Location</button></div><div style="grid-column:1/-1;border-left:0;border-top:1px solid var(--line);margin-top:13px;padding-top:13px" class="muted">Showing professionals who serve this area.</div></div><div class="results-head"><h2 class="section-title">Matching Professionals</h2><span class="muted">${ps.length} results</span></div>${ps.length?ps.map(providerCard).join(''):`<div class="bcard empty-state"><span class="round-icon">⌖</span><h3>No matching professionals yet</h3><p>We couldn’t find a beauty professional serving <b>${esc(S.location)}</b> for this search.</p><button class="btn secondary" onclick="chooseLocation()">Change Location</button></div>`}`}
function providerCard(p){return `<div class="bcard provider-card"><div class="avatar">♙</div><div><h3>${p.name} ${p.verified?'<span class="verified">✓</span>':''}</h3><div class="muted"><b>${p.cats.join(' · ')}</b></div><div class="muted" style="margin-top:4px">${p.services.slice(0,3).join(' · ')}</div><div class="muted" style="margin-top:6px">📍 Serves ${p.areas[0]}${p.areas.length>1?' and nearby areas':''}</div><button class="btn secondary view-btn" onclick="nav('profile',{provider:'${p.id}'})">View Profile ›</button></div></div>`}
function profile(id){let p=B.providers.find(x=>x.id===id)||B.providers[0];let rv=[...B.reviews,...(S.reviews||[])].filter(r=>r.provider===p.id);return head('Beauty Profile','', 'results')+`<div class="bcard profile-hero"><div class="avatar">♙</div><h2>${p.name} ${p.verified?'<span class="verified">✓</span>':''}</h2><div class="chips">${p.cats.map(c=>`<span class="chip">${icon(c)} &nbsp;${c}</span>`).join('')}</div><div class="metric-grid"><div class="metric"><span class="round-icon">⭐</span><div><b>${p.rating}</b><span class="muted">${p.count+(S.extraRatings||0)} ratings</span></div></div><div class="metric"><span class="round-icon">✓</span><div><b>${p.completed+(S.extraCompleted||0)}</b><span class="muted">Services Completed</span></div></div></div></div><div class="bcard content-card"><h2>About</h2><div class="muted">${p.about}</div></div><div class="bcard content-card"><h2>Services</h2><div class="service-list">${p.services.map((x,i)=>`<div class="service-row"><span class="service-icon">${i?icon(p.cats[Math.min(i,p.cats.length-1)]):'💄'}</span>${x}</div>`).join('')}</div></div><div class="bcard content-card"><h2>Service Areas</h2><div class="muted">Areas this professional serves</div>${p.areas.map(x=>`<div class="area-row"><span class="round-icon">⌖</span>${x}</div>`).join('')}</div><button class="btn green" onclick="contact('${p.id}')">◉ &nbsp; Contact on WhatsApp &nbsp; ›</button><div class="bcard content-card"><h2>Ratings & Reviews</h2><div class="reviews-summary"><span class="round-icon">⭐</span><div><b>${p.rating}</b><div class="muted">${p.count+(S.extraRatings||0)} ratings</div></div></div>${rv.length?rv.map(reviewCard).join(''):`<div class="empty">No reviews yet.</div>`}</div>`}
function reviewCard(r){return `<div class="review"><div class="review-top"><div><b>${esc(r.name)}</b><div class="stars">${'★'.repeat(r.stars)}${'☆'.repeat(5-r.stars)}</div></div><span class="muted">${esc(r.date)}</span></div><div class="muted" style="color:var(--plum);margin-top:5px">${esc(r.text)}</div>${r.confirmed?'<span class="confirmed">● Confirmed Service</span>':''}<button class="report">Report Review</button></div>`}
function contact(pid){let id='u'+Date.now();S.contacts=[...(S.contacts||[]),{id,provider:pid,customer:'Tanveer',service:S.category||'Beauty Service',status:'contacted'}];save();alert('HerDay Contact Request created. WhatsApp would now open in production.');}
function createProfile(){let sel=S.newCats===undefined?['Makeup','Bridal Services','Threading & Brows']:S.newCats,sv=S.newServices||['Party Makeup','Bridal Makeup','Engagement Makeup'],ar=S.newAreas||['DHA Phase 5','DHA Phase 6','Askari 11'];if(typeof sv==='string')sv=sv.split(',').map(x=>x.trim()).filter(Boolean);if(typeof ar==='string')ar=ar.split(',').map(x=>x.trim()).filter(Boolean);S.newCats=sel;S.newServices=sv;S.newAreas=ar;let phone=(S.newPhone||'').replace(/^\+?92\s*/, '');return head('Create Beauty Profile','Create your professional presence on HerDay.')+`<div class="create-page"><div class="form-section photo-uploader"><h2>Professional Photo</h2><div class="avatar">${S.newPhoto?`<img src="${S.newPhoto}" alt="Selected professional photo">`:'♙'}</div><label class="upload-label" for="proPhoto">▣ &nbsp; Add Photo</label><input id="proPhoto" class="file-input" type="file" accept="image/*" onchange="selectProfilePhoto(this)"><div class="muted photo-help">This photo will appear on your public Beauty Profile.</div></div><div class="form-section"><h2>Professional / Parlor Name</h2><div class="icon-field"><span>♜</span><input id="proName" class="field" placeholder="e.g. Glam by Ayesha" value="${esc(S.newName||'')}"></div><div class="muted section-help">This is the professional name customers will see.</div></div><div class="form-section"><h2>About</h2><div class="icon-field textarea-icon"><span>▤</span><textarea id="proAbout" class="field" placeholder="Tell customers a little about your beauty services...">${esc(S.newAbout||'')}</textarea></div></div><div class="form-section"><h2>Beauty Categories</h2><div class="muted">Choose the categories you offer.</div><div class="drop"><button class="field category-select" onclick="$('#catDrop').classList.toggle('hidden')"><span>✦ &nbsp; Select categories</span><b>⌄</b></button><div id="catDrop" class="drop-menu hidden">${B.cats.map(c=>`<label><input type="checkbox" ${sel.includes(c)?'checked':''} onchange="toggleCat('${c}',this.checked)">${c}</label>`).join('')}<button class="btn primary small" onclick="$('#catDrop').classList.add('hidden');render()">Done</button></div></div><div class="chips">${sel.map(c=>`<button class="chip" onclick="toggleCat('${c}',false);render()">${c}<span>×</span></button>`).join('')}</div></div><div class="form-section"><h2>Your Services</h2><div class="muted">Add the services you personally offer.</div><div class="dynamic-add"><input id="serviceAdd" class="field" placeholder="✦  Service Name"><button class="btn primary small" onclick="addService()">Add Service</button></div><div class="dynamic-list">${sv.map((x,i)=>`<div class="dynamic-row"><span>⠿ &nbsp; ${esc(x)}</span><span><button aria-label="Edit service" onclick="editService(${i})">♢</button><button aria-label="Remove service" onclick="removeService(${i})">×</button></span></div>`).join('')}</div></div><div class="form-section"><h2>Service Areas</h2><div class="muted">Add the areas where you provide beauty services.</div><div class="dynamic-add"><div class="area-suggest"><input id="areaAdd" class="field" autocomplete="off" placeholder="⌖  Search area" oninput="areaSearch(this.value)"><div id="areaSuggestions" class="area-suggestions hidden"></div></div><button class="btn primary small" onclick="addArea()">Add Area</button></div><div class="muted area-help">Select the correct area name so customers can find you.</div><div class="dynamic-list">${ar.map((x,i)=>`<div class="dynamic-row"><span>📍 &nbsp; ${esc(x)}</span><button aria-label="Remove area" onclick="removeArea(${i})">×</button></div>`).join('')}</div></div><div class="form-section"><h2>WhatsApp Number</h2><div class="phone-field"><span class="wa-icon">◉</span><span class="phone-prefix">+92　⌄</span><input id="proPhone" class="field" inputmode="tel" placeholder="3XX XXXXXXX" value="${esc(phone)}"></div><div class="muted section-help">Customers will use this number to contact you after your profile is approved and live.</div></div><button class="btn primary continue-button" onclick="saveCreate()">Continue to Verification <span>›</span></button><div class="muted next-note">You'll record a live verification video in the next step.</div></div>`}
function toggleCat(c,on){let a=new Set(S.newCats||[]);on?a.add(c):a.delete(c);S.newCats=[...a];save()}
function addService(){let v=$('#serviceAdd').value.trim();if(v){S.newServices=[...(S.newServices||[]),v];save();render()}}function removeService(i){S.newServices.splice(i,1);save();render()}
function editService(i){let current=S.newServices[i],v=prompt('Edit service name',current);if(v!==null&&v.trim()){S.newServices[i]=v.trim();save();render()}}
function selectProfilePhoto(input){let file=input.files&&input.files[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{S.newPhoto=reader.result;save();render()};reader.readAsDataURL(file)}
let areaTimer=null;function areaSearch(q){clearTimeout(areaTimer);let box=$('#areaSuggestions');if(!box)return;q=q.trim();if(!q){box.classList.add('hidden');return}let local=APP_LOCATIONS().filter(x=>x.toLowerCase().includes(q.toLowerCase())).slice(0,5).map(x=>({name:x,detail:'Saved on HerDay'}));showAreaSuggestions(local);if(q.length>=3)areaTimer=setTimeout(async()=>{try{let r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=6&countrycodes=pk&q='+encodeURIComponent(q),{headers:{'Accept':'application/json'}});let d=await r.json();let map=d.map(x=>({name:x.name||x.display_name.split(',')[0],detail:x.display_name}));showAreaSuggestions([...local,...map])}catch(e){}},350)}
function showAreaSuggestions(items){let box=$('#areaSuggestions');if(!box)return;let seen=new Set();items=items.filter(x=>{let k=x.name.toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).slice(0,8);box.innerHTML=items.map(x=>`<button type="button" onclick='pickArea(${JSON.stringify(JSON.stringify(x))})'><b>${esc(x.name)}</b><small class="muted">${esc(x.detail||'')}</small></button>`).join('');box.classList.toggle('hidden',!items.length)}
function pickArea(raw){let x=JSON.parse(raw);$('#areaAdd').value=x.name;$('#areaSuggestions')?.classList.add('hidden');S.pendingArea=x.name}
function addArea(){let v=(S.pendingArea||$('#areaAdd').value).trim();if(v&&!S.newAreas.includes(v)){S.newAreas=[...(S.newAreas||[]),v];S.savedLocations=[...new Set([...(S.savedLocations||[]),v])];S.pendingArea='';save();render()}}function removeArea(i){S.newAreas.splice(i,1);save();render()}
function saveCreate(){S.newName=$('#proName').value.trim();S.newAbout=$('#proAbout').value.trim();let phone=$('#proPhone').value.trim();S.newPhone=phone?'+92 '+phone.replace(/^\+?92\s*/,''):'';S.beautyOwnerId=currentUser()?.id||S.beautyOwnerId||null;save();nav('verify-info')}
function verifyInfo(){let details=['Your Beauty Profile / Professional Name','The beauty services you provide','The areas where you provide your services'],opened=sessionStorage.getItem(VOICE_WHATSAPP_OPENED)==='1';return head('Verify Your Beauty Profile','A quick voice verification before your profile goes live.','create')+`<div class="verify-page voice-verify-page"><div class="bcard verify-hero voice-hero"><div class="big-illus voice-illus">◉<span>✓</span></div><div><h2>Voice Verification</h2><div class="muted">Send us a short voice note from the WhatsApp number you entered in your Beauty Profile.</div><span class="pill voice-only">♪ &nbsp; WhatsApp voice note</span></div></div><div class="bcard content-card voice-details-card"><h2>What to mention</h2><div class="muted intro-copy">Please include only these three details:</div>${details.map((x,i)=>`<div class="voice-detail"><span class="detail-number">${i+1}</span><span>${x}</span></div>`).join('')}</div><div class="bcard voice-reassurance"><span class="reassurance-icon">✓</span><div><b>No video, CNIC or documents required.</b><div class="muted">Your voice note is only used to confirm the details submitted in your Beauty Profile.</div></div></div><button class="btn primary send-voice-note" onclick="openVerificationWhatsApp()"><span class="whatsapp-mark">◉</span> Send Verification Voice Note</button><div class="muted voice-cta-help">WhatsApp will open so you can record and send the voice note yourself.</div><button class="btn secondary confirm-voice-note" onclick="confirmVoiceVerification()" ${opened?'':'disabled'}>I've Sent My Voice Note</button></div>`}
function openVerificationWhatsApp(){sessionStorage.setItem(VOICE_WHATSAPP_OPENED,'1');let confirmButton=$('.confirm-voice-note');if(confirmButton)confirmButton.disabled=false;window.location.href=`https://wa.me/${HERDAY_VERIFICATION_WHATSAPP}`}
function confirmVoiceVerification(){if(sessionStorage.getItem(VOICE_WHATSAPP_OPENED)!=='1')return;sessionStorage.removeItem(VOICE_WHATSAPP_OPENED);S.verification='pending';S.verificationSubmittedAt=new Date().toISOString();save();nav('pending')}

const ADMIN_CHECK_KEYS=['whatsapp','name','services','areas'];
function submittedBeautyProfile(){if(!String(S.newName||'').trim())return null;return {id:'submitted-beauty-profile',name:String(S.newName).trim(),about:String(S.newAbout||'').trim(),photo:S.newPhoto||'',cats:Array.isArray(S.newCats)?S.newCats:[],services:Array.isArray(S.newServices)?S.newServices:[],areas:Array.isArray(S.newAreas)?S.newAreas:[],phone:String(S.newPhone||'').trim(),submittedAt:S.verificationSubmittedAt||null,verification:S.verification||'draft'}}
function pendingBeautyVerifications(){let p=submittedBeautyProfile();return p&&p.verification==='pending'?[p]:[]}
function formatAdminDate(value){if(!value)return 'Not recorded';let d=new Date(value);return Number.isNaN(d.getTime())?'Not recorded':d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}
function adminAvatar(p,extra=''){return `<div class="admin-avatar ${extra}">${p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.name)} professional profile photo">`:'♙'}</div>`}
function beautyVerifications(){let profiles=pendingBeautyVerifications();return `<div class="admin-page-head"><h1>Beauty Verifications</h1><p>Review pending Beauty Profile verifications.</p></div><div class="admin-section-head"><h2>Pending Verifications</h2><span class="admin-count">${profiles.length}</span></div><div class="admin-pending-list">${profiles.length?profiles.map(adminPendingCard).join(''):`<div class="admin-empty"><span>ⓘ</span><div>No pending Beauty Profile verifications.</div></div>`}</div>`}
function adminPendingCard(p){return `<article class="bcard admin-pending-card">${adminAvatar(p)}<div class="admin-pending-main"><div class="admin-card-title"><h3>${esc(p.name)}</h3><span class="status wait">◷ &nbsp; Pending Review</span></div><div class="admin-phone">◉ <span>${esc(p.phone||'No WhatsApp number submitted')}</span></div><div class="chips">${p.cats.map(c=>`<span class="chip">${esc(c)}</span>`).join('')}</div></div><div class="admin-card-foot"><div><span class="admin-calendar">▣</span><span class="muted">Submitted on<br><b>${esc(formatAdminDate(p.submittedAt))}</b></span></div><button class="btn secondary admin-open-review" onclick="openBeautyReview('${p.id}')">Open Review &nbsp;›</button></div></article>`}
function openBeautyReview(id){let p=pendingBeautyVerifications().find(x=>x.id===id);if(!p)return;S.adminReviewId=id;S.adminVerificationChecks={};save();nav('beauty-verification-review')}
function beautyVerificationReview(){let p=submittedBeautyProfile();if(!p||p.id!==S.adminReviewId||p.verification!=='pending')return head('Beauty Verification Review','', 'beauty-verifications')+`<div class="bcard admin-empty"><span>ⓘ</span><div>This pending verification is no longer available.</div></div>`;let checks=S.adminVerificationChecks||{};return head('Beauty Verification Review','', 'beauty-verifications')+`<div class="admin-review-status"><span class="status wait">◷ &nbsp; Pending Review</span></div><div class="bcard admin-review-card admin-professional"><div class="admin-card-heading"><span>♙♙</span><h2>Professional Profile</h2></div><div class="admin-profile-body">${adminAvatar(p,'large')}<div><b class="admin-profile-name">${esc(p.name)}</b><div class="muted">Professional / Parlor Name</div><div class="admin-divider"></div><span class="muted">About</span><p>${esc(p.about||'No About information submitted.')}</p></div></div></div>${adminReadOnlySection('▦','Beauty Categories',p.cats,'categories')}${adminReadOnlySection('☷','Services',p.services,'services')}${adminReadOnlySection('⌖','Service Areas',p.areas,'areas')}<div class="bcard admin-review-card admin-whatsapp"><div class="admin-card-heading"><span>◉</span><h2>WhatsApp Number</h2></div><div class="admin-whatsapp-value"><span>◉</span><div><b>${esc(p.phone||'Not submitted')}</b><div class="muted">Submitted provider number</div></div></div></div><div class="bcard admin-review-card admin-voice-check"><div class="admin-card-heading"><span>▤</span><h2>Voice Verification Check</h2></div><p class="muted">Check the voice note received on the HerDay verification WhatsApp and confirm that the submitted details match.</p><div class="admin-checks">${[['whatsapp','WhatsApp number matches'],['name','Professional / Parlor Name matches'],['services','Services match'],['areas','Service Areas match']].map(x=>`<label><input type="checkbox" ${checks[x[0]]?'checked':''} onchange="toggleAdminCheck('${x[0]}',this.checked)"><span>${x[1]}</span></label>`).join('')}</div><div class="admin-info-note"><span>ⓘ</span>Open WhatsApp separately to review the voice note.</div></div><div class="bcard admin-review-card admin-decision"><div class="admin-card-heading"><span>♢</span><h2>Review Decision</h2></div><p class="muted">Please complete the above checks before deciding on this Beauty Profile verification.</p><div class="admin-decision-actions"><button id="approveBeautyButton" class="btn primary" onclick="showApproveBeautyDialog()" ${adminChecksComplete()?'':'disabled'}>Approve &amp; Verify</button><button class="btn secondary" onclick="showCorrectionDialog()">Needs Correction</button></div></div>`}
function adminReadOnlySection(symbol,title,items,type){return `<div class="bcard admin-review-card"><div class="admin-card-heading"><span>${symbol}</span><h2>${title}</h2></div><div class="admin-readonly-list ${type}">${items.length?items.map(x=>`<div>${type==='areas'?'<span>⌖</span>':''}${esc(x)}</div>`).join(''):`<div class="muted">None submitted</div>`}</div></div>`}
function adminChecksComplete(){let checks=S.adminVerificationChecks||{};return ADMIN_CHECK_KEYS.every(k=>checks[k]===true)}
function toggleAdminCheck(key,checked){if(!ADMIN_CHECK_KEYS.includes(key))return;S.adminVerificationChecks={...(S.adminVerificationChecks||{}),[key]:!!checked};save();let button=$('#approveBeautyButton');if(button)button.disabled=!adminChecksComplete()}
function adminDialog(content){$('#adminDialog')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="adminDialog" class="admin-dialog-backdrop" onclick="if(event.target===this)closeAdminDialog()"><div class="admin-dialog">${content}</div></div>`)}
function closeAdminDialog(){$('#adminDialog')?.remove()}
function showApproveBeautyDialog(){if(!adminChecksComplete())return;adminDialog(`<h2>Approve this Beauty Profile?</h2><p>Confirm that you checked the verification voice note and the submitted Beauty Profile details match.</p><div class="admin-dialog-actions"><button class="btn secondary" onclick="closeAdminDialog()">Cancel</button><button class="btn primary" onclick="approveBeautyVerification()">Approve &amp; Verify</button></div>`)}
function approveBeautyVerification(){if(!adminChecksComplete())return;S.verification='approved';S.beautyVerified=true;S.beautyPublic=true;S.verificationApprovedAt=new Date().toISOString();S.verificationCorrection=null;S.adminVerificationChecks={};save();closeAdminDialog();nav('beauty-verifications')}
function showCorrectionDialog(){let reasons=['WhatsApp number does not match','Professional name does not match','Services do not match','Service areas do not match','Voice note not received / cannot be reviewed','Other'];adminDialog(`<h2>Needs Correction</h2><p>Select the reason and add a short note if needed.</p><div class="admin-reasons">${reasons.map((x,i)=>`<label><input type="radio" name="correctionReason" value="${esc(x)}" ${i===0?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div><textarea id="adminCorrectionNote" class="field" maxlength="300" placeholder="Admin note (optional)"></textarea><div class="admin-dialog-actions"><button class="btn secondary" onclick="closeAdminDialog()">Cancel</button><button class="btn primary" onclick="sendBeautyCorrection()">Send for Correction</button></div>`)}
function sendBeautyCorrection(){let selected=document.querySelector('input[name="correctionReason"]:checked');if(!selected)return;S.verification='needs-correction';S.beautyVerified=false;S.beautyPublic=false;S.verificationCorrection={reason:selected.value,note:$('#adminCorrectionNote')?.value.trim()||'',requestedAt:new Date().toISOString()};S.adminVerificationChecks={};save();closeAdminDialog();nav('beauty-verifications')}
function syncApprovedBeautyProvider(){let id='submitted-beauty-profile',index=B.providers.findIndex(p=>p.id===id);if(index>=0)B.providers.splice(index,1);let p=submittedBeautyProfile();if(!p||S.verification!=='approved'||S.beautyVerified!==true||S.beautyPublic!==true)return;B.providers.push({id,name:p.name,verified:true,cats:p.cats,services:p.services,areas:p.areas,about:p.about||'Beauty professional on HerDay.',rating:0,count:0,completed:0,photo:p.photo})}
let stream=null,rec=null,chunks=[],recTimer=null,recSeconds=0;
async function startCamera(){if($('#cameraScreen'))return;document.body.insertAdjacentHTML('beforeend',cameraHTML());const start=$('#startRec');start.disabled=true;$('#camMsg').textContent='Opening camera…';try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:true});const v=$('#camVideo');v.srcObject=stream;await new Promise(res=>{if(v.readyState>=2)return res();v.onloadedmetadata=()=>res()});await v.play();start.disabled=false;setCameraState('ready');$('#camMsg').textContent='Ready to record'}catch(e){$('#camMsg').textContent='Camera permission is required for live verification.'}}
function cameraHTML(){return `<div id="cameraScreen" class="camera-screen"><div class="camera-inner"><div class="camera-top"><button class="back" onclick="closeCamera()">×</button><b>Live Verification</b><span class="muted">Step 1 of 1</span></div><div class="camera-box"><video id="camVideo" autoplay muted playsinline></video><div class="camera-tip">Keep your face clearly visible</div><div class="face-guide"></div></div><div class="instruction"><div class="muted" style="color:#d1c5cf">Current instruction</div><b>Look directly at the camera</b><div class="muted" style="color:#d1c5cf">Keep your face inside the guide.</div></div><div id="readyBadge" class="ready-badge">● <span id="camMsg">Opening camera…</span></div><div class="camera-actions"><button id="stopRec" class="cam-action" disabled onclick="recordStop()"><span class="cam-circle">■</span>Stop Recording</button><button id="retake" class="cam-action state-hidden" onclick="retake()"><span class="cam-circle">↻</span>Retake</button><button id="startRec" class="cam-action" disabled onclick="recordStart()"><span class="cam-circle">●</span><span id="startLabel">Start Recording</span></button><button id="submitRec" class="cam-action primary" disabled onclick="submitVerification()"><span class="cam-circle">➤</span>Submit for Review</button></div><div class="progress">1 Record &nbsp; — &nbsp; 2 Stop &nbsp; — &nbsp; 3 Submit</div><div class="notice">▣ &nbsp; Your verification video is private.<br><span style="margin-left:24px">It will be permanently deleted after your verification is approved.</span></div><div class="camera-help">Need help?</div></div></div>`}
function setCameraState(state){let st=$('#startRec'),sp=$('#stopRec'),rt=$('#retake'),sb=$('#submitRec'),badge=$('#readyBadge');if(!st)return;st.classList.toggle('state-hidden',state!=='ready');sp.classList.toggle('state-hidden',state!=='recording');rt.classList.toggle('state-hidden',state!=='recorded');sb.classList.toggle('state-hidden',state==='recording');st.disabled=state!=='ready'||!(stream&&stream.active);sp.disabled=state!=='recording';rt.disabled=state!=='recorded';sb.disabled=state!=='recorded'||!chunks.length;badge?.classList.toggle('recording',state==='recording')}
function recordStart(){if(!stream||!stream.active||!window.MediaRecorder){$('#camMsg').textContent='Camera recorder is not ready';return}chunks=[];let opts={};for(const t of ['video/webm;codecs=vp8,opus','video/webm;codecs=vp8','video/webm']){if(MediaRecorder.isTypeSupported?.(t)){opts.mimeType=t;break}}try{rec=new MediaRecorder(stream,opts)}catch(e){try{rec=new MediaRecorder(stream)}catch(err){$('#camMsg').textContent='Recording is not supported in this browser';return}}rec.ondataavailable=e=>{if(e.data&&e.data.size>0)chunks.push(e.data)};rec.onerror=()=>{$('#camMsg').textContent='Recording error — please Retake';setCameraState('ready')};rec.onstop=()=>{clearInterval(recTimer);setTimeout(()=>{if(chunks.length){$('#camMsg').textContent='Video ready';setCameraState('recorded')}else{$('#camMsg').textContent='Recording failed — Retake';setCameraState('ready')}},120)};rec.start(200);recSeconds=0;setCameraState('recording');$('#camMsg').textContent='REC 00:00';recTimer=setInterval(()=>{recSeconds++;$('#camMsg').textContent=`REC ${String(Math.floor(recSeconds/60)).padStart(2,'0')}:${String(recSeconds%60).padStart(2,'0')}`},1000)}
function recordStop(){if(rec&&rec.state==='recording'){try{rec.requestData()}catch(e){};setTimeout(()=>{if(rec&&rec.state==='recording')rec.stop()},80)}}
function retake(){clearInterval(recTimer);chunks=[];rec=null;$('#camMsg').textContent='Ready to record';setCameraState('ready')}
function closeCamera(){clearInterval(recTimer);if(rec&&rec.state==='recording'){try{rec.stop()}catch(e){}}stream?.getTracks().forEach(t=>t.stop());stream=null;$('#cameraScreen')?.remove()}
function submitVerification(){if(!chunks.length)return;S.verification='pending';save();closeCamera();nav('pending')}
function pending(){setTimeout(()=>{$('.beauty-head')?.classList.add('pending-head');$('.beauty-shell')?.classList.add('pending-page')},0);return head('Verification Submitted','', 'beauty-main')+`<div class="bcard verify-hero"><div class="big-illus">♪✓</div><div><h2>Verification Submitted</h2><span class="status wait">◷ &nbsp; Pending Review</span><div class="muted" style="margin-top:10px">Your Beauty Profile verification has been submitted successfully. HerDay will review the details provided for your Beauty Profile.</div></div></div><div class="bcard content-card"><h2>What happens next?</h2><div class="steps">${[['▤','Details Submitted'],['✓','HerDay Review'],['♙','Profile Approved']].map(x=>`<div><span class="step-icon">${x[0]}</span><div class="muted">${x[1]}</div></div>`).join('')}</div><div class="muted" style="margin-top:14px">Your Beauty Profile remains pending while HerDay reviews the submitted details.<br><br>After approval, your Beauty Profile can go live with HerDay verification status.</div></div><div class="bcard row"><span class="round-icon">♙</span><div><b style="font:20px DMSerif,Georgia,serif">Beauty Profile</b><div><span class="status wait">◷ Awaiting Verification Approval</span></div><div class="muted">Your Beauty Profile will not appear in public provider searches until verification is approved.</div></div></div><div class="bcard row"><span class="round-icon">▣</span><div><b>Your submitted verification details are used to review your Beauty Profile.</b><div class="muted">HerDay compares the submitted details with the information in your Beauty Profile.</div></div></div><div class="bcard row"><span class="round-icon">ⓘ</span><div><b>No action is needed while your verification is under review.</b><div class="muted">You do not need to send anything else unless HerDay requests a correction.</div></div></div><button class="btn primary" onclick="nav('beauty-main')">Back to Beauty Services</button><div style="text-align:center;margin:15px;color:var(--pink)">Need help?</div>`}
function allContacts(){return [...B.contacts,...(S.contacts||[])]}
function contacts(){let cs=allContacts().map(c=>S.baseOverrides?.[c.id]?{...c,status:S.baseOverrides[c.id]}:c);return head('Service Contacts','Manage customers who contacted you through HerDay.','beauty-main')+`<div class="bcard row"><span class="round-icon">♙♙</span><div><b style="font:21px DMSerif,Georgia,serif">Service Contacts</b><div class="muted">Customers who contacted your Beauty Profile through HerDay appear here.</div></div></div>${cs.map(c=>`<div class="bcard contact-card"><div class="avatar">♙</div><div><div class="row between"><h3>${esc(c.customer)}</h3>${status(c.status)}</div><div class="muted">Contacted through HerDay</div><div class="muted" style="margin-top:12px">Service</div><b>${esc(c.service)}</b></div>${c.status==='contacted'?`<button class="btn primary full" onclick="markDone('${c.id}')">Mark Service Completed</button>`:''}</div>`).join('')}`}
function status(s){let m={contacted:['● Contacted',''],waiting:['● Waiting for Customer Confirmation','wait'],confirmed:['● Completed & Confirmed','done'],no:['● Not Confirmed','no']};let x=m[s]||[s,''];return `<span class="status ${x[1]}">${x[0]}</span>`}
function markDone(id){if(confirm('Mark service as completed?\nConfirm that you provided this beauty service.')){setStatus(id,'waiting');S.confirmId=id;save();nav('confirm')}}
function getContact(id){let c=(S.contacts||[]).find(x=>x.id===id)||B.contacts.find(x=>x.id===id);if(c&&S.baseOverrides?.[id])return {...c,status:S.baseOverrides[id]};return c}
function confirmService(){let c=getContact(S.confirmId||'c2')||B.contacts[1];return head('Confirm Service','Please confirm your recent beauty service.','beauty-main')+`<div class="bcard row"><div class="avatar">♙</div><h2 style="font:26px DMSerif,Georgia,serif">Glam by Ayesha <span class="verified">✓</span></h2></div><div class="bcard"><span class="pill">✓ &nbsp; Service Completed</span><p class="muted">Provider has marked this service as completed.</p><div class="row"><span class="round-icon">✿</span><b style="font:20px DMSerif,Georgia,serif">${esc(c.service)}</b></div></div><div class="bcard content-card"><h2>Did you receive this service?</h2><p class="muted">Confirm only if you actually received a beauty service from this professional.</p><button class="btn primary" onclick="confirmYes('${c.id}')">Yes, I Received the Service</button><div style="height:10px"></div><button class="btn secondary" onclick="confirmNo('${c.id}')">No, I Didn’t Receive the Service</button><p class="muted" style="margin-top:17px">Confirming Yes will unlock one Rate & Review opportunity for this completed service.</p><p class="muted">Selecting No will not unlock rating or review.</p></div>`}
function setStatus(id,st){let c=(S.contacts||[]).find(x=>x.id===id);if(c)c.status=st;else S.baseOverrides={...(S.baseOverrides||{}),[id]:st};save()}
function confirmYes(id){setStatus(id,'confirmed');S.rateId=id;S.extraCompleted=(S.extraCompleted||0)+1;save();nav('rate')}function confirmNo(id){setStatus(id,'no');alert('Service marked Not Confirmed. Rating was not unlocked.');nav('beauty-main')}
function rate(){let c=getContact(S.rateId||'c3')||B.contacts[2];return head('Rate Your Experience','Share your experience with this beauty professional.','beauty-main')+`<div class="bcard row"><div class="avatar">♙</div><div><h2 style="font:25px DMSerif,Georgia,serif;margin:0">Glam by Ayesha <span class="verified">✓</span></h2><span class="pill">✓ &nbsp; Service confirmed</span></div></div><div class="bcard content-card"><h2>How was your experience?</h2><div class="rating-stars">${['Poor','Fair','Good','Very Good','Excellent'].map((x,i)=>`<div class="star-choice"><button class="${(S.tempStars||0)>i?'on':''}" onclick="S.tempStars=${i+1};save();render()">☆</button>${i+1}<br>${x}</div>`).join('')}</div></div><div class="bcard content-card"><h2>Write a Review</h2><textarea id="reviewText" class="field" placeholder="Tell others about your experience...">${esc(S.tempReview||'')}</textarea><div class="muted">You can edit your rating and review before submitting.</div></div><button class="btn primary" onclick="submitReview('${c.id}')">Submit Review</button>`}
function submitReview(id){let stars=S.tempStars||0,text=$('#reviewText').value.trim();if(!stars){alert('Please select a star rating.');return}if(!text){alert('Please write a review.');return}S.reviews=[...(S.reviews||[]),{provider:'ayesha',name:'Tanveer',stars,date:new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),text,confirmed:true,contact:id}];S.extraRatings=(S.extraRatings||0)+1;S.tempStars=0;S.tempReview='';save();nav('profile',{provider:'ayesha'})}
window.nav=nav;window.openProfile=openProfile;window.loginAccount=loginAccount;window.createAccount=createAccount;window.socialAuth=socialAuth;window.forgotPassword=forgotPassword;window.signOut=signOut;window.showPlaceholder=showPlaceholder;window.showEditProfileDialog=showEditProfileDialog;window.savePersonalProfile=savePersonalProfile;window.nearMe=nearMe;window.closeLocationSearch=closeLocationSearch;window.locationInput=locationInput;window.selectLocation=selectLocation;window.areaSearch=areaSearch;window.pickArea=pickArea;window.toggleCat=toggleCat;window.chooseLocation=chooseLocation;window.addService=addService;window.removeService=removeService;window.editService=editService;window.selectProfilePhoto=selectProfilePhoto;window.addArea=addArea;window.removeArea=removeArea;window.saveCreate=saveCreate;window.openVerificationWhatsApp=openVerificationWhatsApp;window.confirmVoiceVerification=confirmVoiceVerification;window.startCamera=startCamera;window.closeCamera=closeCamera;window.recordStart=recordStart;window.recordStop=recordStop;window.retake=retake;window.submitVerification=submitVerification;window.contact=contact;window.markDone=markDone;window.confirmYes=confirmYes;window.confirmNo=confirmNo;window.submitReview=submitReview;window.openBeautyVerifications=()=>nav('beauty-verifications');window.openBeautyReview=openBeautyReview;window.toggleAdminCheck=toggleAdminCheck;window.showApproveBeautyDialog=showApproveBeautyDialog;window.showCorrectionDialog=showCorrectionDialog;window.closeAdminDialog=closeAdminDialog;window.approveBeautyVerification=approveBeautyVerification;window.sendBeautyCorrection=sendBeautyCorrection;
window.render=render;
